       font-size: 0.8rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(1.75rem, 3vw, 2.1rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0 0 24px;
       color: var(--muted);
       line-height: 1.5;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       padding: 16px;
       border: 1px solid rgba(37, 99, 235, 0.12);
       border-radius: 18px;
       background: rgba(248, 250, 252, 0.9);
     }

     .checkbox-row {
       display: flex;
       gap: 12px;
       align-items: flex-start;
     }

     input[type="checkbox"] {
       width: 18px;
       height: 18px;
       margin-top: 3px;
       accent-color: var(--accent);
       cursor: pointer;
       flex: 0 0 auto;
     }

     label {
       font-weight: 600;
       line-height: 1.45;
       cursor: pointer;
     }

     .helper-text {
       margin: 8px 0 0 30px;
       font-size: 0.92rem;
       line-height: 1.45;
       color: var(--muted);
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 14px 18px;
       font: inherit;
       font-weight: 700;
       color: #fff;
       background: linear-gradient(135deg, var(--accent), var(--accent-dark));
       cursor: pointer;
       transition: transform 120ms ease, box-shadow 120ms ease;
       box-shadow: 0 16px 32px rgba(37, 99, 235, 0.24);
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:active {
       transform: translateY(0);
     }

     .status {
       min-height: 24px;
       margin: 0;
       font-size: 0.95rem;
       font-weight: 600;
     }

     .status.success {
       color: var(--success-text);
       background: var(--success-bg);
       border-radius: 12px;
       padding: 10px 12px;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <p class="eyebrow">Quick confirmation</p>
     <h1>Agree to continue</h1>
     <p class="intro">Please confirm that you accept the terms of use before submitting.</p>

     <form id="consent-form">
       <div class="form-field">
         <div class="checkbox-row">
           <input id="terms" name="terms" type="checkbox" required>
           <label for="terms">I agree to the terms of use.</label>
         </div>
         <p class="helper-text">Required to complete your submission.</p>
       </div>

       <button type="submit">Submit</button>
       <p id="status" class="status" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById("consent-form");
     const status = document.getElementById("status");

     form.addEventListener("submit", function (event) {
       event.preventDefault();
       status.textContent = "Consent recorded. Thanks for confirming.";
       status.className = "status success";
     });
   </script>
 </body>
 </html>

